<?php
declare(strict_types=1);
namespace App\Cms;
use Symfony\Component\HttpFoundation\File\UploadedFile;
use Symfony\Component\HttpKernel\Exception\BadRequestHttpException;
final class CmsDownloadStorage { private const EXTENSIONS=['pdf','zip','txt','csv','xml']; private const MIMES=['pdf'=>['application/pdf'],'zip'=>['application/zip','application/x-zip-compressed'],'txt'=>['text/plain'],'csv'=>['text/plain','text/csv'],'xml'=>['application/xml','text/xml','text/plain']]; private string $directory; public function __construct(string $projectDir){$this->directory=$projectDir.'/var/storage/cms-downloads';} public function store(UploadedFile $file):array{if(!$file->isValid()||($file->getSize()??0)>50*1024*1024)throw new BadRequestHttpException('Die Datei ist ungültig oder größer als 50 MB.');$extension=strtolower($file->getClientOriginalExtension());$mime=$file->getMimeType()??'';if(!in_array($extension,self::EXTENSIONS,true)||!in_array($mime,self::MIMES[$extension]??[],true))throw new BadRequestHttpException('Dieser Dateityp ist nicht erlaubt.');if(!is_dir($this->directory)&&!mkdir($this->directory,0770,true)&&!is_dir($this->directory))throw new \RuntimeException('Download-Speicher konnte nicht erstellt werden.');$stored=bin2hex(random_bytes(24)).'.'.$extension;$file->move($this->directory,$stored);return ['path'=>$stored,'original'=>basename(str_replace('\\','/',$file->getClientOriginalName())),'mime'=>$mime,'size'=>filesize($this->path($stored))];} public function path(string $stored):string{if($stored!==basename($stored)||!preg_match('/^[a-f0-9]{48}\.(pdf|zip|txt|csv|xml)$/',$stored))throw new \InvalidArgumentException('Invalid stored filename.');return $this->directory.'/'.$stored;} public function exists(string $stored):bool{try{return is_file($this->path($stored));}catch(\InvalidArgumentException){return false;}} public function delete(?string $stored):void{if($stored!==null&&$this->exists($stored))@unlink($this->path($stored));}}
